// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 a, uint64 b) public {
        vm.assume(a != b);
        vm.assume(b != 0);

        vm.startPrank(depositor);
        c.setL1BlockValues(1, 1, 1, bytes32(uint256(1)), a, bytes32(uint256(1)), 1, 1);
        c.setL1BlockValues(2, 2, 2, bytes32(uint256(2)), b, bytes32(uint256(2)), 2, 2);
        vm.stopPrank();

        assertTrue(c.sequenceNumber() == b);
    }
}
